import test from'node:test';import assert from'node:assert/strict';
import{create,simulate,basePrice,noiseAt,compareSharing,upgradeSettings}from'./engine.js';
test('actions change price before it becomes noisy information for the next estimate',()=>{const s=create(),r=simulate(s);for(let i=0;i<39;i++){const a=r.history[i],b=r.history[i+1];assert.ok(Math.abs(a.price-a.base-s.impact*a.mean)<1e-10);assert.ok(Math.abs(b.shared-a.shared-s.reaction*(a.price+s.noise*noiseAt(s.seed,i,-1)-a.shared))<1e-10);}});
test('removing price impact removes the self-induced outcome',()=>{const s=create(),r=simulate({...s,impact:0});assert.ok(r.history.every(row=>row.price===basePrice(s.scenario,row.tick)));});
test('sharing alone cannot change outcomes with noiseless matched signals',()=>{for(const reaction of [.05,.35,.9]){const s={...create(),noise:0,reaction};const r=compareSharing(s);assert.deepEqual(r.shared,r.separate);assert.deepEqual(simulate({...s,common:s.common.map((_,i)=>i%2===0)}),r.shared);}});
test('private estimates use the same speed, starting value and noise amplitude',()=>{const s={...create(),common:Array(24).fill(false)},r=simulate(s);assert.ok(r.history[0].signals.every(v=>v===s.initial));for(let t=0;t<39;t++)for(let i=0;i<24;i++){const before=r.history[t],next=r.history[t+1];assert.ok(Math.abs(next.signals[i]-before.signals[i]-s.reaction*(before.price+s.noise*noiseAt(s.seed,t,i)-before.signals[i]))<1e-10);}});
test('fast feedback can oscillate in either group without observation noise',()=>{const s={...create(),noise:0};for(const common of [Array(24).fill(true),Array(24).fill(false)]){const fast=simulate({...s,common,reaction:.9}),slow=simulate({...s,common,reaction:.1});assert.deepEqual(fast.history.map(r=>r.base),slow.history.map(r=>r.base));assert.ok(fast.oscillation>slow.oscillation);for(const r of fast.history)assert.ok(r.actions.every(x=>x>=-1&&x<=1));}});
test('matched noise replays are repeatable and noise samples can be challenged',()=>{const s=create();assert.deepEqual(compareSharing(s),compareSharing(s));assert.notDeepEqual(simulate(s).history,simulate({...s,seed:2}).history);assert.deepEqual(compareSharing(s).shared.history.map(r=>r.base),compareSharing(s).separate.history.map(r=>r.base));});
test('old settings upgrade without overwriting their original data',()=>{const old=create();delete old.noise;delete old.seed;const copy=structuredClone(old),s=upgradeSettings(old);assert.equal(s.noise,0);assert.equal(s.seed,1);assert.deepEqual(old,copy);assert.equal(s.reaction,old.reaction);});
